import{_ as e,c as i,o,a2 as s}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"Política de Privacidad","description":"qDiff no recopila sus datos. Descubra qué lee la aplicación en su Mac y cómo se gestionan las compras.","frontmatter":{"title":"Política de Privacidad","description":"qDiff no recopila sus datos. Descubra qué lee la aplicación en su Mac y cómo se gestionan las compras."},"headers":[],"relativePath":"es/privacy/index.md","filePath":"es/privacy/index.md","lastUpdated":1794296122000}'),n={name:"es/privacy/index.md"};function c(r,a,t,l,d,p){return o(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="politica-de-privacidad" tabindex="-1">Política de Privacidad <a class="header-anchor" href="#politica-de-privacidad" aria-label="Permalink to &quot;Política de Privacidad&quot;">​</a></h1><p><em>Última actualización: 6 de noviembre de 2026</em></p><p><strong>En resumen: qDiff no recopila datos personales.</strong> Es una herramienta local. Sus archivos permanecen en su Mac.</p><h2 id="que-lee-qdiff" tabindex="-1">Qué lee qDiff <a class="header-anchor" href="#que-lee-qdiff" aria-label="Permalink to &quot;Qué lee qDiff&quot;">​</a></h2><p>qDiff abre únicamente los archivos y carpetas que usted elige en la aplicación y los procesa en su dispositivo para mostrar la comparación. Si concede acceso a una carpeta, ese acceso se conserva para su comodidad y puede revocarse en Ajustes en cualquier momento. No se nos envía nada.</p><h2 id="lo-que-no-hacemos" tabindex="-1">Lo que no hacemos <a class="header-anchor" href="#lo-que-no-hacemos" aria-label="Permalink to &quot;Lo que no hacemos&quot;">​</a></h2><ul><li>No recopilamos nombres, direcciones de correo electrónico ni estadísticas de uso.</li><li>No le rastreamos entre aplicaciones ni sitios web.</li><li>No exigimos ninguna cuenta ni inicio de sesión.</li><li>No mostramos publicidad ni incluimos análisis de datos ni seguimiento de terceros.</li><li>No sincronizamos ni enviamos copias de sus archivos a ningún servidor.</li></ul><h2 id="acceso-a-la-red" tabindex="-1">Acceso a la red <a class="header-anchor" href="#acceso-a-la-red" aria-label="Permalink to &quot;Acceso a la red&quot;">​</a></h2><p>qDiff funciona sin conexión. La única solicitud de red opcional es la página «Más Apps» dentro de la aplicación, que carga una lista pública de aplicaciones. Esa solicitud no contiene información sobre usted, sus archivos o su dispositivo, y no se devuelve ningún dato de uso.</p><h2 id="compras" tabindex="-1">Compras <a class="header-anchor" href="#compras" aria-label="Permalink to &quot;Compras&quot;">​</a></h2><p>La compra única opcional la gestionan íntegramente el Mac App Store y su Apple ID. Nunca vemos sus datos de pago. Puede restaurar una compra desde Ajustes dentro de la aplicación.</p><h2 id="este-sitio-web" tabindex="-1">Este sitio web <a class="header-anchor" href="#este-sitio-web" aria-label="Permalink to &quot;Este sitio web&quot;">​</a></h2><p>Este sitio es un conjunto de páginas estáticas. No tiene inicio de sesión, ni análisis de datos, ni cookies publicitarias. Abrir una página no le obliga a facilitarnos nada.</p><h2 id="menores" tabindex="-1">Menores <a class="header-anchor" href="#menores" aria-label="Permalink to &quot;Menores&quot;">​</a></h2><p>qDiff no está dirigido a menores y no recopila información de nadie de forma consciente.</p><h2 id="cambios" tabindex="-1">Cambios <a class="header-anchor" href="#cambios" aria-label="Permalink to &quot;Cambios&quot;">​</a></h2><p>Si esta política llegara a cambiar, actualizaremos esta página y la fecha indicada arriba. Cualquier cambio que afecte a lo que la aplicación lee también se describirá dentro de la propia aplicación.</p><h2 id="contacto" tabindex="-1">Contacto <a class="header-anchor" href="#contacto" aria-label="Permalink to &quot;Contacto&quot;">​</a></h2><p>¿Tiene preguntas sobre privacidad? Escriba a <a href="mailto:qdiff@w3cub.com" target="_blank" rel="noreferrer">qdiff@w3cub.com</a>.</p>',19)])])}const h=e(n,[["render",c]]);export{m as __pageData,h as default};
